(function(){
  function cls(n){ return Java.loadClass(n); }
  var State = cls("com.merlinkitsune.astral_dice.shop.ChipShopState");
  var Opener = cls("com.merlinkitsune.astral_dice.shop.ChipShopOpener");
  var player = AutoJS.players()[0];
  var out = {};
  player.closeContainer();
  State.store(player, State.EMPTY);
  Opener.open(player);
  var m = player.containerMenu;
  out.menuIsShop = String(m).indexOf("ChipShopMenu") >= 0;
  if (!out.menuIsShop) { out.abort = true; return out; }
  out.abort = false;
  out.priceBefore = m.price();
  out.refreshesBefore = m.remainingRefreshes();
  out.totalRefreshes = m.totalRefreshes();
  out.keyBefore = String(m.offersKey());
  out.stateRefreshesBefore = State.get(player).refreshesLeft();
  m.handleRefresh(player);
  out.refreshesAfter = m.remainingRefreshes();
  out.stateRefreshesAfter = State.get(player).refreshesLeft();
  out.priceAfter = m.price();
  out.keyChanged = String(State.get(player).offersKey()) !== out.keyBefore;
  out.menuStillOpen = String(player.containerMenu).indexOf("ChipShopMenu") >= 0;
  out.serverKey = String(State.get(player).offersKey());
  return out;
})()

(function(){
  function cls(n){ return Java.loadClass(n); }
  var mc = cls("net.minecraft.client.Minecraft").getInstance();
  var out = {};
  var sc = mc.screen;
  out.screenClass = (sc == null) ? "" : String(sc);
  var menu = (mc.player == null) ? null : mc.player.containerMenu;
  out.menuClass = (menu == null) ? "" : String(menu);
  if (menu == null) { out.abort = true; return out; }
  out.abort = false;
  out.clientPrice = menu.price();
  out.clientRefreshes = menu.remainingRefreshes();
  out.clientTotal = menu.totalRefreshes();
  out.clientKey = String(menu.offersKey());
  out.clientDeny = menu.denyReason();
  try {
    var State = cls("com.merlinkitsune.astral_dice.shop.ChipShopState");
    out.syncedRefreshes = State.get(mc.player).refreshesLeft();
    out.syncedPrice = State.get(mc.player).price();
  } catch (e) { out.syncErr = String(e); }
  return out;
})()

